// parentScope is the predicate of the records under parent.
func (r *GraphQLMenuRepository) parentScope(ctx context.Context, parent string) ([]graphql.Predicate, error) {
	parentIDs, err := repox.SplitName(parent, "venues")
	if err != nil {
		return nil, err
	}
	// AIP-159: "-" for the parent reads across every parent. A "-" widens
	// only its own segment: under a parent naming some of its ancestors
	// ("a/1/b/-"), the records' own names are matched, so they stay under
	// those.
	if parentIDs[len(parentIDs)-1] == "-" {
		if repox.AllWild(parentIDs) {
			return nil, nil
		}
		p, _ := repox.NamePattern(parent + "/menus/-")
		return []graphql.Predicate{menusql.Name.Like(p)}, nil
	}
	return []graphql.Predicate{menusql.VenueId.Eq(parentIDs[len(parentIDs)-1])}, nil
}

// engine is the list engine over the records scope selects (and, unless
// in.ShowDeleted, not deleted), with in's filter conditions.
func (r *GraphQLMenuRepository) engine(in repox.ListInput, scope ...graphql.Predicate) (*filterx.HasuraEngine[menusql.CatalogMenus], []filterx.Condition, error) {
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, nil, repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	eng := filterx.Hasura[menusql.CatalogMenus](catalog.MenuFilterSpec, r.Svc.Query.Catalog.Menus).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	return eng, conds, nil
}

// count is Count over scope: one aggregate, unless a condition is matched
// page by page (one reaching another table, or a hint), when the matching
// rows are counted, at most repox.GraphQLScanLimit of them.
func (r *GraphQLMenuRepository) count(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) (int64, error) {
	eng, conds, err := r.engine(in, scope...)
	if err != nil {
		return 0, err
	}
	if repox.ReachesVia(catalog.MenuFilterSpec, conds) || repox.AnyHint(conds) {
		var n int64
		err := r.scan(ctx, eng, conds, func(*menusql.CatalogMenus) { n++ })
		return n, err
	}
	where, has, err := eng.Predicate(conds)
	if err != nil {
		return 0, repox.MapFilterxErr(err)
	}
	if has {
		scope = append(scope, where)
	}
	req := menusql.Aggregate()
	if len(scope) > 0 {
		req = req.Where(graphql.And(scope...))
	}
	agg, err := r.Svc.Query.Catalog.Menus.Aggregate(ctx, req)
	if err != nil || agg == nil {
		return 0, mapGraphQLErr(err)
	}
	return int64(agg.Count), nil
}

// facet is Facet over scope, counted from the matching rows, at most
// repox.GraphQLScanLimit of them (more fail with repox.ErrInvalidArgument, as
// count's do). A field reached through another table -- a value object's, a
// join table's -- is counted from that table's rows the matching rows reach
// (repox.FacetVia).
func (r *GraphQLMenuRepository) facet(ctx context.Context, in repox.ListInput, field string, limit int, scope ...graphql.Predicate) ([]repox.Bucket, error) {
	spec := catalog.MenuFilterSpec
	if _, err := repox.FacetExpr(spec, field); err != nil {
		return nil, err
	}
	eng, conds, err := r.engine(in, scope...)
	if err != nil {
		return nil, err
	}
	if f, ok := spec.Fields[field]; ok && f.Via != nil {
		return nil, fmt.Errorf("%w: facet by %q, reached through another table, on GraphQL", repox.ErrInvalidArgument, field)
	}
	counts := map[string]int64{}
	if err := r.scan(ctx, eng, conds, func(row *menusql.CatalogMenus) {
		for _, v := range repox.FacetValues(spec, field, repox.RowMap(row)) {
			counts[v]++
		}
	}); err != nil {
		return nil, err
	}
	return repox.SortBuckets(counts, limit), nil
}

// scan calls f for every row eng matches under conds, failing past
// repox.GraphQLScanLimit rows.
func (r *GraphQLMenuRepository) scan(ctx context.Context, eng *filterx.HasuraEngine[menusql.CatalogMenus], conds []filterx.Condition, f func(*menusql.CatalogMenus)) error {
	in := filterx.ListInput{PageSize: 1000, Filter: conds}
	for read := 0; ; {
		rows, next, err := eng.List(ctx, in)
		if err != nil {
			return repox.MapFilterxErr(err)
		}
		for i := range rows {
			f(&rows[i])
		}
		read += len(rows)
		if next == "" {
			return nil
		}
		if read >= repox.GraphQLScanLimit {
			return fmt.Errorf("%w: more than %d rows to scan on GraphQL; narrow the filter", repox.ErrInvalidArgument, repox.GraphQLScanLimit)
		}
		in.PageToken = next
	}
}

func (r *GraphQLMenuRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*catalogpbv1.Menu, string, error) {
	if err := repox.CheckReadMask((*catalogpbv1.Menu)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng, conds, err := r.engine(in, scope...)
	if err != nil {
		return nil, "", err
	}
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*catalogpbv1.Menu, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

// Update persists the masked fields of in; an empty mask replaces every
