	patch := menuToUpdatePatch(merged)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	if in.GetEtag() != "" {
		if _, err := r.Svc.Mutation.Catalog.Menus.UpdateIfMatch(ctx, id, patch, menusql.Etag.Eq(in.GetEtag())); err != nil {
			return nil, mapGraphQLErr(err)
		}
		return r.get(ctx, id)
	}
	resp, err := r.Svc.Mutation.Catalog.Menus.Update(ctx, id, patch)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return nil, repox.ErrNotFound
	}
	return r.get(ctx, id)
