// updateOps queues Update's writes onto ops, for a Batch: the value-object
// rows that replace the masked ones, the row update, then the removal of what
// they replaced. With in.Etag set the update is guarded inside the batch: a
// self-update of the key whose post-check asserts the etag fails the request
// when the record moved on, and the guarded update after it writes the row.
//
// outputPaths names the server-owned fields written alongside
// (Update<Model>WithOutputOnly); nil for Update.
func (r *GraphQLMenuRepository) updateOps(ctx context.Context, ops *repox.Ops, id string, in *catalogpbv1.Menu, paths, outputPaths []string) (repox.Check, error) {
	row, err := r.Svc.Query.Catalog.Menus.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := menuFromRow(row)
	if in.GetEtag() != "" && existingPB.GetEtag() != in.GetEtag() {
		return nil, repox.ErrConflict
	}
	merged := proto.Clone(existingPB).(*catalogpbv1.Menu)
	applyMenuMask(merged, in, paths)
	if err := checkMenuRequired(merged); err != nil {
		return nil, err
	}
	patch := menuToUpdatePatch(merged)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	var utx, atx repox.Ops
	*ops = append(*ops, utx...)
	resp := new(menusql.UpdateCatalogMenusByIdResponse)
	etag := in.GetEtag()
	if etag != "" {
		ops.Add(r.Svc.Mutation.Catalog.Menus.UpdateOp(id, menusql.UpdateInput{Id: graphql.Value(id)}, new(menusql.UpdateCatalogMenusByIdResponse), menusql.Update().PostCheck(menusql.Etag.Eq(etag))))
		ops.Add(r.Svc.Mutation.Catalog.Menus.UpdateOp(id, patch, resp, menusql.Update().PreCheck(menusql.Etag.Eq(etag))))
	} else {
		ops.Add(r.Svc.Mutation.Catalog.Menus.UpdateOp(id, patch, resp))
	}
	*ops = append(*ops, atx...)
	return func(ctx context.Context, failed error) error {
		if failed == nil {
			if resp.AffectedRows == 0 {
				if etag != "" {
					return repox.ErrConflict
				}
				return repox.ErrNotFound
			}
			return nil
		}
		// The request failed; if this guard is why, say so.
		if etag != "" {
			if now, err := r.Svc.Query.Catalog.Menus.Get(ctx, id); err == nil && (now == nil || menuFromRow(now).GetEtag() != etag) {
				return repox.ErrConflict
			}
		}
		return nil
	}, nil
}

