// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u   *repox.Unit
	svc *aperioql.Service
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateDish queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateDish(parent string, in *catalogpbv1.Dish) (string, error) {
	r := &GraphQLDishRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueDishReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		ops.Add(b.svc.Mutation.Catalog.Dishes.CreateOp(ci, new(dishesql.InsertCatalogDishesResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "aperio.catalog.v1/Dish", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateDish queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateDish(in *catalogpbv1.Dish, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "venues", "dishes"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLDishRepository{Svc: b.svc}
	queueDishReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "aperio.catalog.v1/Dish", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getDish)})
}

// DeleteDish queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) DeleteDish(name string) {
	if _, err := repox.SplitName(name, "venues", "dishes"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLDishRepository{Svc: b.svc}
	queueDishDelete(b.u, name, true)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Catalog.Dishes.DeleteOp(id, new(dishesql.DeleteCatalogDishesByIdResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "aperio.catalog.v1/Dish", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getDish)})
}

